# Look at the 7s
print("\n7s:")
for r in range(len(grid)):
    for c in range(len(grid[0])):
        if grid[r][c] == 7:
            print(f"  (row={r}, col={c})")

# Look at the 2s
print("\n2s:")
for r in range(len(grid)):
    for c in range(len(grid[0])):
        if grid[r][c] == 2:
            print(f"  (row={r}, col={c})")

# The 5s seem to form some kind of pattern
# Let me find all 5 cells
print("\n5s:")
for r in range(len(grid)):
    for c in range(len(grid[0])):
        if grid[r][c] == 5:
            print(f"  (row={r}, col={c})")

# Pattern analysis: The 7s look like they form a filled region
# Let me check if the 7s have a shape

# Let me try a simple hypothesis: change all 7s to 5s
output_grid = [row[:] for row in grid]
for r in range(len(output_grid)):
    for c in range(len(output_grid[0])):
        if output_grid[r][c] == 7:
            output_grid[r][c] = 5

print("Output grid (7s -> 5s):")
for row in output_grid:
    print(row)

# Try another hypothesis: change all 2s to 7s
output_grid = [row[:] for row in grid]
for r in range(len(output_grid)):
    for c in range(len(output_grid[0])):
        if output_grid[r][c] == 2:
            output_grid[r][c] = 7

print("Output grid (2s -> 7s):")
for row in output_grid:
    print(row)

# Try swapping 2 and 7
output_grid = [row[:] for row in grid]
# First change 2 to temp
for r in range(len(output_grid)):
    for c in range(len(output_grid[0])):
        if output_grid[r][c] == 2:
            output_grid[r][c] = 1  # temp value
# Then change 7 to 2
for r in range(len(output_grid)):
    for c in range(len(output_grid[0])):
        if output_grid[r][c] == 7:
            output_grid[r][c] = 2
# Then change temp back to 7
for r in range(len(output_grid)):
    for c in range(len(output_grid[0])):
        if output_grid[r][c] == 1:
            output_grid[r][c] = 7

print("Output grid (2<->7 swapped):")
for row in output_grid:
    print(row)

# Try removing all 2s and 7s (they become 0)
output_grid = [row[:] for row in grid]
for r in range(len(output_grid)):
    for c in range(len(output_grid[0])):
        if output_grid[r][c] == 2 or output_grid[r][c] == 7:
            output_grid[r][c] = 0

print("Output grid (2s and 7s -> 0s):")
for row in output_grid:
    print(row)

# Try: 7s become 0, keep 2s
output_grid = [row[:] for row in grid]
for r in range(len(output_grid)):
    for c in range(len(output_grid[0])):
        if output_grid[r][c] == 7:
            output_grid[r][c] = 0

print("Output grid (7s -> 0s, keep 2s):")
for row in output_grid:
    print(row)

# Let me try yet another hypothesis
# What if I need to replace all non-5 non-0 values with 5?
output_grid = [row[:] for row in grid]
for r in range(len(output_grid)):
    for c in range(len(output_grid[0])):
        if output_grid[r][c] not in [0, 5]:
            output_grid[r][c] = 5

print("Output grid (non-0, non-5 -> 5):")
for row in output_grid:
    print(row)

# I'm running out of guesses. Let me try a simple pattern
# Maybe just: 2s become 7s (or 2s become 0s)

# Let me try: all 2s become 0
output_grid = [row[:] for row in grid]
for r in range(len(output_grid)):
    for c in range(len(output_grid[0])):
        if output_grid[r][c] == 2:
            output_grid[r][c] = 0

print("Output grid (2s -> 0s):")
for row in output_grid:
    print(row)

# Try: 7s become 2s
output_grid = [row[:] for row in grid]
for r in range(len(output_grid)):
    for c in range(len(output_grid[0])):
        if output_grid[r][c] == 7:
            output_grid[r][c] = 2

print("Output grid (7s -> 2s):")
for row in output_grid:
    print(row)

